import {execFileSync,spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {existsSync,lstatSync,mkdtempSync,readFileSync,realpathSync,rmSync,statSync} from 'node:fs';
import {isAbsolute, join} from 'node:path';
import {DatabaseSync} from 'node:sqlite';
import {tmpdir} from 'node:os';

import {afterImmediateCommit, auditEvent, beforeImmediateCommit, openControlPlaneDb, resolveControlPlanePaths, withImmediateTransaction} from './control-plane-db.mjs';
import {openRolloutDb} from './rollout-db.mjs';
import {initializeWrapperPointer,inspectWrapperPointer,switchWrapperPointer} from './rollout-wrapper-pointer.mjs';
import {invokePinnedAuthority} from './external-rollout-authority.mjs';
import {loadPinnedRolloutWrapper} from './rollout-wrapper-dispatcher.mjs';

const STAGES=['observe','warn','enforce_paths','enforce_resources','mandatory'];
const ZERO=`sha256:${'0'.repeat(64)}`;
const SHA=/^[0-9a-f]{40}$/;
const DIGEST=/^sha256:[0-9a-f]{64}$/;
const canonical=value=>value===null||typeof value!=='object'?JSON.stringify(value):Array.isArray(value)?`[${value.map(canonical).join(',')}]`:`{${Object.keys(value).sort().map(key=>`${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
const sha=value=>`sha256:${createHash('sha256').update(value).digest('hex')}`;
const isTest=options=>process.env.NODE_ENV==='test'&&process.env.CHAOTANG_CONTROL_PLANE_TEST_ADAPTER==='1'&&options.testAdapter===true;
function now(options,input){if((input!==undefined||options.nowMs!==undefined)&&!isTest(options))throw new Error('production wall clock cannot be overridden');return input??options.nowMs??Date.now();}

function parseRolloutPolicy(tracked,commit){
  let policy;try{policy=JSON.parse(tracked);}catch{throw new Error('rollout policy JSON invalid');}
  if(policy?.schema_version!==1||typeof policy.policy_version!=='string'||STAGES.some(stage=>!Number.isFinite(policy.stages?.[stage]?.minimum_ms))||policy.thresholds?.minimum_window_tasks!==20||policy.thresholds?.consecutive_releases!==20||!isAbsolute(policy.external?.rollout_anchor_command??'')||!DIGEST.test(policy.external?.rollout_anchor_command_digest??''))throw new Error('rollout policy contract invalid');
  return{...policy,commit,digest:sha(tracked)};
}
export function loadRolloutPolicy(cwd=process.cwd(),pinnedCommit=null){
  const root=resolveControlPlanePaths(cwd).repositoryRoot,path='.harness/policy/control-plane-rollout.json';
  let commit,tracked,working;
  try{commit=pinnedCommit??execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim();if(!SHA.test(commit))throw new Error('invalid commit');tracked=execFileSync('git',['show',`${commit}:${path}`],{cwd:root,encoding:'utf8'});if(!pinnedCommit)working=readFileSync(join(root,path),'utf8');}catch{throw new Error('rollout policy must be a clean committed Git object');}
  if(!pinnedCommit&&(tracked!==working||!lstatSync(join(root,path)).isFile()||lstatSync(join(root,path)).isSymbolicLink()))throw new Error('rollout policy must match its clean committed Git object');
  return parseRolloutPolicy(tracked,commit);
}
function trackedDirt(cwd){const root=resolveControlPlanePaths(cwd).repositoryRoot,lines=execFileSync('git',['status','--porcelain=v1','--untracked-files=no'],{cwd:root,encoding:'utf8'}).trim().split('\n').filter(Boolean);return{dirty:lines.length>0,count:lines.length,digest:sha(canonical(lines))};}

const TEST_POLICY={schema_version:1,policy_version:'test-only',stages:Object.fromEntries(STAGES.map(stage=>[stage,{minimum_ms:0}])),thresholds:{minimum_window_tasks:20,duplicate_work_reduction:.8,observation_conflicts:0,data_completeness:1,false_positive_warn:.02,false_positive_rollback:.05,path_false_positive_rollback:.02,max_task_overhead_seconds:300,max_release_block_seconds:900,consecutive_releases:20},external:{},wrapper:{stable:'test-stable',candidate:'test-candidate'}};
function policy(options){if(options.policy){if(!isTest(options))throw new Error('rollout policy injection is test-only');return{...options.policy,commit:options.policyCommit??'a'.repeat(40),digest:sha(canonical(options.policy))};}if(isTest(options))return{...TEST_POLICY,commit:'a'.repeat(40),digest:sha(canonical(TEST_POLICY))};const cwd=options.cwd??process.cwd(),rolloutPath=join(resolveControlPlanePaths(cwd).runtimeDir,'rollout.sqlite3');if(existsSync(rolloutPath)){let db;try{db=new DatabaseSync(rolloutPath,{readOnly:true});const row=db.prepare('SELECT policy_commit FROM rollout_state WHERE singleton=1').get();if(row?.policy_commit)return loadRolloutPolicy(cwd,row.policy_commit);}catch(error){throw new Error(`cannot load rollout pinned policy: ${error.message}`);}finally{try{db?.close();}catch{}}}return loadRolloutPolicy(cwd);}
function append(db,event,payload,at){const prior=db.prepare('SELECT sequence,event_hash FROM rollout_events ORDER BY sequence DESC LIMIT 1').get(),sequence=(prior?.sequence??0)+1,previous=prior?.event_hash??ZERO,eventHash=sha(canonical({sequence,event,payload,previous,created_at:at}));db.prepare('INSERT INTO rollout_events(sequence,event,payload_json,previous_hash,event_hash,created_at) VALUES(?,?,?,?,?,?)').run(sequence,event,canonical(payload),previous,eventHash,at);db.prepare('UPDATE rollout_state SET event_sequence=?,event_hash=?,updated_at=? WHERE singleton=1').run(sequence,eventHash,at);return{sequence,digest:eventHash};}
function anchor(options,event,{required=false}={}){if(typeof options.externalAuthority==='function'){if(!isTest(options))throw new Error('caller-supplied external authority is test-only');try{const result=options.externalAuthority(event);if(result?.verified!==true)throw new Error('external rollout anchor rejected event');return result;}catch(error){if(required||/rollback|tamper|rejected/i.test(error.message))throw error;return{verified:false,status:'ANCHOR_PENDING',error_digest:sha(error.message)};}}const p=policy(options),command=p.external?.rollout_anchor_command,digest=p.external?.rollout_anchor_command_digest;if(command){let result;try{result=invokePinnedAuthority({command,digest,input:`${canonical(event)}\n`});}catch(error){if(!required&&/ENOENT|EACCES|unavailable|timed out|timeout/i.test(error.message))return{verified:false,status:'ANCHOR_PENDING',error_digest:sha(error.message)};throw new Error(`external rollout anchor unavailable: ${error.message}`);}if(result?.verified!==true){if(!required)return{verified:false,status:'ANCHOR_PENDING'};throw new Error('external rollout anchor rejected event');}return result;}if(required)throw new Error('external rollout monotonic trust anchor is not configured');return{verified:false,status:'EXTERNAL_REQUIRED'};}
function ledgerCheckpoints(db,state){let stage='observe';return db.prepare('SELECT sequence,event,payload_json,event_hash FROM rollout_events ORDER BY sequence').all().map(row=>{const payload=JSON.parse(row.payload_json);if(row.event==='rollout.started')stage='observe';else if(row.event==='rollout.advanced'||row.event==='rollout.auto_rollback')stage=payload.to;return{sequence:row.sequence,digest:row.event_hash,event:row.event,payload,stage,policy_digest:state.policy_digest};});}
function syncAuthority(db,options,{required=false}={}){const state=rawState(db);if(isTest(options)&&options.replayAuthority!==true)return anchor(options,{action:'verify',sequence:state.event_sequence,digest:state.event_hash,stage:state.stage,policy_digest:state.policy_digest},{required});try{const remote=anchor(options,{action:'head',policy_digest:state.policy_digest},{required:true}),events=ledgerCheckpoints(db,state);if(!Number.isInteger(remote.sequence)||remote.sequence<0||remote.sequence>events.length)throw new Error('external authority head sequence invalid');const expected=remote.sequence===0?ZERO:events[remote.sequence-1].digest;if(remote.digest!==expected)throw new Error('external authority head diverges from local ledger');for(const checkpoint of events.slice(remote.sequence)){const accepted=anchor(options,{action:'append',...checkpoint},{required:true});if(accepted.sequence!==checkpoint.sequence||accepted.digest!==checkpoint.digest)throw new Error('external authority append acknowledgement mismatch');}return anchor(options,{action:'verify',sequence:state.event_sequence,digest:state.event_hash,stage:state.stage,policy_digest:state.policy_digest},{required:true});}catch(error){if(required||/diverge|rollback|mismatch|invalid/i.test(error.message))throw error;return{verified:false,status:'ANCHOR_PENDING',error_digest:sha(error.message)};}}
function verifyAnchor(options,state,{required=false,db}={}){if(db)return syncAuthority(db,options,{required});if(isTest(options)&&options.replayAuthority!==true)return anchor(options,{action:'verify',sequence:state.event_sequence,digest:state.event_hash,stage:state.stage,policy_digest:state.policy_digest},{required});const openedDb=opened(options);try{return syncAuthority(openedDb.db,options,{required});}finally{openedDb.db.close();}}
function rawState(db){const state=db.prepare('SELECT * FROM rollout_state WHERE singleton=1').get();if(!state)return state;let stage=null,stageStartedAt=null;for(const row of db.prepare("SELECT event,payload_json,created_at FROM rollout_events WHERE event IN ('rollout.started','rollout.advanced','rollout.auto_rollback') ORDER BY sequence").all()){const payload=JSON.parse(row.payload_json);if(row.event==='rollout.started'){stage='observe';stageStartedAt=row.created_at;}else{stage=payload.to;stageStartedAt=row.created_at;}}if(stage!==null&&(state.stage!==stage||state.stage_started_at!==stageStartedAt))throw new Error('rollout state stage/time differs from immutable ledger');return state;}
function assertPinnedPolicy(state,p){if(state.policy_commit!==p.commit||state.policy_digest!==p.digest)throw new Error('rollout policy differs from the pinned start policy; reviewed migration required');}
function assertWrapperPointer(state,options){const p=policy(options),pointer=inspectWrapperPointer(options.cwd??process.cwd()),expected=p.wrapper?.artifacts?.[state.wrapper_version]?.digest;if(!pointer||pointer.version!==state.wrapper_version||pointer.policy_digest!==state.policy_digest||pointer.artifact_digest!==expected)throw new Error('active wrapper pointer differs from rollout state or pinned artifact');loadPinnedRolloutWrapper({cwd:options.cwd??process.cwd(),commit:state.policy_commit,policy:p,version:state.wrapper_version});return pointer;}
function verifyLocalLedger(db,state){let previous=ZERO,sequence=0;const events=[];for(const row of db.prepare('SELECT * FROM rollout_events ORDER BY sequence').all()){sequence++;if(row.sequence!==sequence||row.previous_hash!==previous)throw new Error('rollout ledger sequence/hash link invalid');const payload=JSON.parse(row.payload_json),expected=sha(canonical({sequence:row.sequence,event:row.event,payload,previous:row.previous_hash,created_at:row.created_at}));if(row.event_hash!==expected)throw new Error('rollout ledger event hash invalid');previous=row.event_hash;events.push({event:row.event,payload});}if(state&&(state.event_sequence!==sequence||state.event_hash!==previous))throw new Error('rollout state/ledger head mismatch');const facts=[['rollout_task_metrics','rollout.task_metric','task_id','task_id'],['rollout_release_metrics','rollout.release','release_id','release_id'],['rollout_acceptance','rollout.acceptance','acceptance_id','id']];for(const[table,event,key,payloadKey]of facts){const rows=db.prepare(`SELECT * FROM ${table}`).all(),matching=events.filter(item=>item.event===event);if(rows.length!==matching.length)throw new Error(`${table} facts/event completeness mismatch`);for(const row of rows){const hits=matching.filter(item=>item.payload[payloadKey]===row[key]);if(hits.length!==1)throw new Error(`${table} fact lacks unique ledger event`);const payload=hits[0].payload;if(table==='rollout_task_metrics'&&(payload.window!==row.window||payload.source_audit_id!==(row.source_audit_id??null)))throw new Error('task metric fact/event binding mismatch');if(table==='rollout_release_metrics'&&(payload.outcome!==row.outcome||payload.external_verified!==Boolean(row.external_verified)||payload.incident!==Boolean(row.incident)))throw new Error('release fact/event binding mismatch');if(table==='rollout_acceptance'&&(payload.commit!==row.commit_sha||payload.artifact_digest!==row.artifact_digest||payload.checkpoint_digest!==sha(row.external_checkpoint)))throw new Error('acceptance fact/event binding mismatch');}}return{sequence,digest:previous};}
function assertClock(state,at){if(at<Date.parse(state.last_seen_at))throw new Error('wall-clock rollback detected');}
function touch(db,state,at){assertClock(state,at);db.prepare('UPDATE rollout_state SET last_seen_at=?,updated_at=? WHERE singleton=1').run(new Date(at).toISOString(),new Date(at).toISOString());}
function opened(options){return openRolloutDb(options);}
function controlOpened(options){return openControlPlaneDb({cwd:options.cwd,databasePath:options.databasePath});}
const rolloutTransactions=new WeakMap();
function withRolloutTransaction(db,options,fn){
  if(rolloutTransactions.has(db))throw new Error('nested rollout transaction forbidden');
  const pending={events:0,required:false};rolloutTransactions.set(db,pending);
  try{
    const value=withImmediateTransaction(db,()=>{const result=fn();if(options.beforeRolloutCommit!==undefined){if(!isTest(options)||typeof options.beforeRolloutCommit!=='function')throw new Error('rollout commit hook is test-only');options.beforeRolloutCommit();}return result;});
    if(pending.events>0)syncAuthority(db,options,{required:pending.required});
    return value;
  }finally{rolloutTransactions.delete(db);}
}
function eventAndAnchor(db,options,event,payload,at,{required=false}={}){let transaction=rolloutTransactions.get(db);if(!transaction){if(!db.isTransaction)throw new Error('rollout event must be appended inside its local transaction');transaction={events:0,required:false};rolloutTransactions.set(db,transaction);if(options.beforeRolloutCommit!==undefined){if(!isTest(options)||typeof options.beforeRolloutCommit!=='function')throw new Error('rollout commit hook is test-only');beforeImmediateCommit(db,options.beforeRolloutCommit);}afterImmediateCommit(db,()=>{try{if(transaction.events>0)syncAuthority(db,options,{required:transaction.required});}finally{rolloutTransactions.delete(db);}});}const checkpoint=append(db,event,payload,at);transaction.events+=1;transaction.required ||= required;return checkpoint;}

export function startRollout(input={},options={}){const p=policy(options),atMs=now(options,input.nowMs),at=new Date(atMs).toISOString(),dirt=isTest(options)?{dirty:false,count:0,digest:sha('test')} : trackedDirt(options.cwd??process.cwd()),pointer=initializeWrapperPointer({cwd:options.cwd??process.cwd(),version:p.wrapper.stable,policyDigest:p.digest}),control=controlOpened(options);try{withImmediateTransaction(control.db,()=>{control.db.prepare("INSERT OR REPLACE INTO control_meta(key,integer_value) VALUES('rollout_activation',1)").run();auditEvent(control.db,{event:'rollout.activation_marked',actor:'rollout-controller',subject:p.commit,payload:{policy_digest:p.digest,pointer_generation:pointer.generation}});});}finally{control.db.close();}const o=opened(options);try{return withImmediateTransaction(o.db,()=>{const existing=rawState(o.db);if(existing)return{stage:existing.stage,status:existing.status,startedAt:existing.stage_started_at,idempotent:true};o.db.prepare('INSERT INTO rollout_state(singleton,stage,status,policy_commit,policy_digest,stage_started_at,last_seen_at,event_sequence,event_hash,wrapper_version,created_at,updated_at) VALUES(1,?,?,?,?,?,?,0,?,?,?,?)').run('observe','ROLLOUT',p.commit,p.digest,at,at,ZERO,p.wrapper.stable,at,at);eventAndAnchor(o.db,options,'rollout.started',{stage:'observe',policy_commit:p.commit,policy_digest:p.digest,tracked_dirt:dirt},at);return{stage:'observe',status:'ROLLOUT',startedAt:at,trackedDirt:dirt};});}finally{o.db.close();}}

function summarizeTasks(db,p){const rows=db.prepare('SELECT * FROM rollout_task_metrics ORDER BY recorded_at,task_id').all(),minimum=p.thresholds.minimum_window_tasks,byWindow={};for(const window of ['baseline','observation']){const classes=new Map();for(const row of rows.filter(item=>item.window===window)){if(!classes.has(row.task_class))classes.set(row.task_class,[]);classes.get(row.task_class).push(row);}byWindow[window]=classes;}const comparableClasses=[...byWindow.baseline.keys()].filter(name=>(byWindow.baseline.get(name)?.length??0)>=minimum&&(byWindow.observation.get(name)?.length??0)>=minimum).sort(),selectedClass=comparableClasses[0]??null,result={};for(const window of ['baseline','observation']){const items=selectedClass?byWindow[window].get(selectedClass).slice(0,minimum):[],steps=items.reduce((n,row)=>n+row.total_steps,0),duplicates=items.reduce((n,row)=>n+row.duplicate_steps,0);result[window]={count:items.length,classes:selectedClass?[selectedClass]:[],complete:items.length>=minimum&&items.every(row=>row.data_complete===1),duplicateRatio:steps?duplicates/steps:null,conflicts:items.reduce((n,row)=>n+row.path_conflicts+row.port_conflicts+row.build_conflicts,0),falsePositiveRate:items.length?items.filter(row=>row.false_positive).length/items.length:null,maxOverheadSeconds:items.length?Math.max(...items.map(row=>row.overhead_seconds)):null};}return{...result,comparable:Boolean(selectedClass),taskClass:selectedClass};}
function guardStats(db,stage){const telemetry=db.prepare("SELECT payload_json FROM rollout_events WHERE event='rollout.telemetry'").all().map(row=>JSON.parse(row.payload_json)).filter(row=>row.stage===stage),guards=db.prepare("SELECT payload_json FROM rollout_events WHERE event='rollout.guard'").all().map(row=>JSON.parse(row.payload_json)).filter(row=>row.stage===stage),rows=telemetry.length?telemetry:guards,count=rows.length,falsePositives=rows.filter(row=>row.false_positive).length;return{count,falsePositiveRate:count?falsePositives/count:0,maxOverheadSeconds:rows.length?Math.max(...rows.map(row=>Number(row.overhead_seconds??0))):0,p0Misblocked:rows.some(row=>row.p0_misblocked===true),maxReleaseBlockedSeconds:rows.length?Math.max(...rows.map(row=>Number(row.release_blocked_seconds??0))):0};}
function collectAuthoritativeTelemetry(db,options,at){const state=rawState(db),seen=new Set(db.prepare("SELECT payload_json FROM rollout_events WHERE event='rollout.telemetry'").all().map(row=>JSON.parse(row.payload_json).source_audit_id)),control=controlOpened(options);try{const rows=control.db.prepare("SELECT id,event,subject,payload_json FROM audit_events WHERE created_at>=? AND event IN ('task.metrics.finalized','control.false_positive_confirmed','release.failed','release.resumed','release.interrupted_recovered','release.incident','rollout.release_incident','resource.conflict') ORDER BY id").all(state.created_at);for(const row of rows){if(seen.has(row.id))continue;let payload={};try{payload=JSON.parse(row.payload_json);}catch{}let blocked=0;if(row.event.startsWith('release.')){const release=control.db.prepare('SELECT created_at,updated_at FROM release_runs WHERE release_id=?').get(row.subject);if(release)blocked=Math.max(0,(Date.parse(release.updated_at)-Date.parse(release.created_at))/1000);}append(db,'rollout.telemetry',{source_audit_id:row.id,source_event:row.event,stage:state.stage,false_positive:row.event==='control.false_positive_confirmed'||payload.falsePositive===true,overhead_seconds:Number(payload.overheadSeconds??payload.control_overhead_seconds??0),p0_misblocked:payload.p0===true||payload.severity==='P0',release_blocked_seconds:blocked},at);}}finally{control.db.close();}}
export function evaluateRollout(options={}){const p=policy(options),o=opened(options);try{const state=rawState(o.db);if(!state)return{eligible:false,failures:['rollout not started']};assertPinnedPolicy(state,p);assertWrapperPointer(state,options);verifyLocalLedger(o.db,state);const metrics=summarizeTasks(o.db,p),failures=[];if(!metrics.comparable)failures.push('baseline/observation task classes are not comparable');for(const name of ['baseline','observation']){const window=metrics[name];if(window.count<p.thresholds.minimum_window_tasks)failures.push(`${name} requires 20 authoritative tasks`);if(!window.complete)failures.push(`${name} data completeness must be 100%`);}if(metrics.baseline.duplicateRatio===null||metrics.observation.duplicateRatio===null)failures.push('duplicate work baseline is unknown');else if(metrics.baseline.duplicateRatio<=0)failures.push('duplicate work baseline must be non-zero to prove an 80% reduction');else if(1-metrics.observation.duplicateRatio/metrics.baseline.duplicateRatio<p.thresholds.duplicate_work_reduction)failures.push('duplicate work reduction below 80%');if(metrics.observation.conflicts!==p.thresholds.observation_conflicts)failures.push('observation conflict count must be zero');if((metrics.observation.falsePositiveRate??1)>=p.thresholds.false_positive_warn)failures.push('false positive rate must be below 2%');if((metrics.observation.maxOverheadSeconds??Infinity)>p.thresholds.max_task_overhead_seconds)failures.push('task overhead exceeds threshold');return{eligible:failures.length===0,failures,metrics};}finally{o.db.close();}}

function activeSnapshot(options){const control=controlOpened(options);try{return{leases:control.db.prepare("SELECT lease_id,task_id,owner,resource,state,fencing_epoch FROM leases WHERE state='active' ORDER BY lease_id").all(),locks:control.db.prepare("SELECT resource_key,owner,task_id,state,fencing_epoch FROM resource_locks WHERE state IN ('active','suspect') ORDER BY resource_key").all()};}finally{control.db.close();}}
function transition(db,options,state,to,reason,at,p,{automatic=false}={}){const snapshot=activeSnapshot(options),wrapper={from:state.wrapper_version,to:automatic?p.wrapper.stable:(to==='enforce_resources'||to==='mandatory'?p.wrapper.candidate:state.wrapper_version)};db.prepare('INSERT INTO rollout_snapshots(from_stage,to_stage,reason,wrapper_json,active_state_json,event_sequence,event_hash,created_at) VALUES(?,?,?,?,?,?,?,?)').run(state.stage,to,reason,canonical(wrapper),canonical(snapshot),state.event_sequence,state.event_hash,at);const status=to==='mandatory'?'ENFORCED':'ROLLOUT';db.prepare('UPDATE rollout_state SET stage=?,status=?,stage_started_at=?,last_seen_at=?,wrapper_version=?,updated_at=? WHERE singleton=1').run(to,status,at,at,wrapper.to,at);return eventAndAnchor(db,options,automatic?'rollout.auto_rollback':'rollout.advanced',{from:state.stage,to,reason,wrapper,snapshot_counts:{leases:snapshot.leases.length,locks:snapshot.locks.length}},at,{required:!automatic});}
function autoRollback(db,options,state,p,at){const stats=guardStats(db,state.stage);let target;if(state.stage==='warn'&&(stats.falsePositiveRate>p.thresholds.false_positive_rollback||stats.maxOverheadSeconds>p.thresholds.max_task_overhead_seconds))target='observe';if(state.stage==='enforce_paths'&&(stats.p0Misblocked||stats.falsePositiveRate>p.thresholds.path_false_positive_rollback))target='warn';if(state.stage==='enforce_resources'&&stats.maxReleaseBlockedSeconds>p.thresholds.max_release_block_seconds)target='enforce_paths';if(target)transition(db,options,state,target,'automatic threshold rollback',at,p,{automatic:true});return target;}

export function guardRolloutOperation(input,options={}){if(!isTest(options)&&['falsePositive','overheadSeconds','p0Misblocked','releaseBlockedSeconds'].some(key=>input[key]!==undefined))throw new Error('production guard telemetry must come from authoritative audit, not caller input');if(!['path','resource','release'].includes(input.kind)||typeof input.compliant!=='boolean'||!input.actor||!input.subject)throw new Error('rollout guard input invalid');const p=policy(options),at=new Date(now(options,input.nowMs)).toISOString(),o=opened(options);let result;try{result=withImmediateTransaction(o.db,()=>{let state=rawState(o.db);if(!state)return{allowed:true,stage:'observe',status:'not_started'};assertPinnedPolicy(state,p);assertWrapperPointer(state,options);verifyLocalLedger(o.db,state);touch(o.db,state,Date.parse(at));const requiresSynchronousAnchor=['enforce_paths','enforce_resources','mandatory'].includes(state.stage);verifyAnchor(options,state,{required:requiresSynchronousAnchor});collectAuthoritativeTelemetry(o.db,options,at);const enforced=state.stage==='mandatory'||state.stage==='enforce_resources'||(state.stage==='enforce_paths'&&input.kind==='path'),warn=state.stage==='warn'&&!input.compliant;if(warn&&(!input.continue?.reason||input.continue.reason.length<3))throw new Error('Warn violation requires audited manual continue reason');const allowed=input.compliant||!enforced;eventAndAnchor(o.db,options,'rollout.guard',{stage:state.stage,kind:input.kind,compliant:input.compliant,allowed,actor:input.actor,subject:input.subject,false_positive:input.falsePositive===true,overhead_seconds:input.overheadSeconds??0,p0_misblocked:input.p0Misblocked===true,release_blocked_seconds:input.releaseBlockedSeconds??0,continue_reason:input.continue?.reason??null},at,{required:requiresSynchronousAnchor});state=rawState(o.db);autoRollback(o.db,options,state,p,at);const next=rawState(o.db);if(requiresSynchronousAnchor)verifyAnchor(options,next,{required:true});return{allowed,stage:next.stage,blockedStage:state.stage,warning:warn,pointerFrom:state.wrapper_version,pointerTo:next.wrapper_version,policyDigest:state.policy_digest};});}finally{o.db.close();}if(result.pointerFrom&&result.pointerFrom!==result.pointerTo)switchWrapperPointer({cwd:options.cwd??process.cwd(),expectedVersion:result.pointerFrom,nextVersion:result.pointerTo,policyDigest:result.policyDigest});const{pointerFrom,pointerTo,policyDigest,...publicResult}=result;if(!publicResult.allowed)throw new Error(`rollout ${publicResult.blockedStage} blocked noncompliant ${input.kind} operation`);return publicResult;}

const WRAPPER_DISPATCHERS={
  stable:(input,options)=>{const openedDb=opened(options);try{const state=rawState(openedDb.db);if(state&&!['observe','warn','enforce_paths'].includes(state.stage))throw new Error('stable wrapper cannot execute candidate rollout stage');}finally{openedDb.db.close();}return guardRolloutOperation(input,options);},
  candidate:(input,options)=>{const openedDb=opened(options);try{const state=rawState(openedDb.db);if(state&&!['enforce_resources','mandatory'].includes(state.stage))throw new Error('candidate wrapper cannot execute stable rollout stage');}finally{openedDb.db.close();}return guardRolloutOperation(input,options);},
};
